for row,s in random.sample(srcl,3): print(row["scientific_name"],row["Location_name"] or "Glenorie",row["Age at first flower production from seed_repr3"],row["Time to 50% flowering"],"| SRC",s)
with open("data/inference_test/results/sonnet-5-5.csv","a",newline="") as f:
    w=csv.DictWriter(f,COLS,lineterminator="\n"); w.writerows(out)
print(len(out))
